        /// <summary>
        /// Get list detail of package by package id
        /// </summary>
        /// <returns>List detail of package</returns>
        public List<MEPackageItemsInfo> GetPackageItemsByPackageID(int packageID)
        {
            DataSet ds = dal.GetDataSet("MEPackageItems_MEPackageItemsByPackageID", packageID);
            List<MEPackageItemsInfo> packageList = new List<MEPackageItemsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    MEPackageItemsInfo objPackageItemsInfo = (MEPackageItemsInfo)GetObjectFromDataRow(row);
                    packageList.Add(objPackageItemsInfo);
                }
            }
            return packageList;
        }
        public MEPackageItemsInfo GetPackageItemByCheckListItemIDAndPakageID(int productID, int packageID)
        {
            DataSet ds = dal.GetDataSet("MEPackageItems_GetPackageItemByCheckListItemIDAndPakageID", productID, packageID);
            if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
            {
                MEPackageItemsInfo objPackageItems = (MEPackageItemsInfo)GetObjectFromDataRow(ds.Tables[0].Rows[0]);
                return objPackageItems;
            }
            return null;
        }
    }
